out = subprocess.run([binary, 'extract', '-s', src, '--no-cache', '--html-attributes', 'none', '-j'], capture_output=True, text=True)
if out.returncode not in (0, 1):
    print(out.stderr[-600:])
d = json.loads(out.stdout)
if not names:
    print(json.dumps(d)[:1800])
    sys.exit()


