    if isinstance(node, dict):
        if node.get('displayName') == comp or node.get('name') == comp:
            yield node
        for v in node.values():
            yield from walk(v)
    elif isinstance(node, list):
        for v in node:
            yield from walk(v)


for found in walk(d):
    print(json.dumps(found)[:3000])
    break

