/// Escape a TOON field value if it contains commas, newlines, or quotes.
fn escape_toon_val(val: &str) -> String {
    if val.contains(',') || val.contains('\n') || val.contains('"') {
        format!("\"{}\"", val.replace('"', "\\\"").replace('\n', " "))
    } else {
        val.to_string()
    }
}

